insert into public.test_knowledge (subjects, grade_min, grade_max, kind, title, body, source_url, status, origin, verified_at) values
  ('{accounting,ems,economic and management}', 7, 12, 'term', 'CRJ (Cash Receipts Journal)', 'CRJ always means Cash Receipts Journal. It records ALL money received by the business: cash sales, payments received from debtors, rent income and other income, capital contributed by the owner, loans received. The Bank column is debited. Source documents: cash register roll, receipts, deposit slip.', 'https://www.twinkl.com/teaching-wiki/crj-and-cpj', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 7, 12, 'term', 'CPJ (Cash Payments Journal)', 'CPJ always means Cash Payments Journal. It records ALL money paid out by the business: cash purchases, payments to creditors, expenses such as rent, salaries and bank charges, and drawings. The Bank column is credited. Source documents: cheque counterfoil, EFT proof of payment.', 'https://www.twinkl.com/teaching-wiki/crj-and-cpj', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 8, 12, 'term', 'DJ (Debtors Journal)', 'The Debtors Journal (also called the sales journal) records CREDIT sales only. Source document: the copy of the sales invoice.', 'https://brainscape.com/flashcards/tracking-41-11895703/packs/20780155', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 8, 12, 'term', 'CJ (Creditors Journal)', 'The Creditors Journal (also called the purchases journal) records CREDIT purchases only. Cash purchases go in the Cash Payments Journal. Source document: the supplier''s original invoice.', 'https://www.graemecollege.co.za/media/1234/grade-9-ems-creditors-notes.pdf', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 9, 12, 'term', 'DAJ (Debtors Allowances Journal)', 'The Debtors Allowances Journal (sales returns journal) records goods returned by customers or allowances given to them. Source document: credit note issued.', 'https://brainscape.com/flashcards/tracking-41-11895703/packs/20780155', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 9, 12, 'term', 'CAJ (Creditors Allowances Journal)', 'The Creditors Allowances Journal (purchases returns journal) records goods returned to suppliers or allowances received. Source document: credit note received from the supplier (debit note issued by the business).', 'https://brainscape.com/flashcards/tracking-41-11895703/packs/20780155', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 9, 12, 'term', 'PCJ (Petty Cash Journal)', 'The Petty Cash Journal records small cash payments made from the petty cash box. Source document: petty cash voucher.', 'https://brainscape.com/flashcards/tracking-41-11895703/packs/20780155', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 9, 12, 'term', 'GJ (General Journal)', 'The General Journal records transactions that fit no other journal: corrections of errors, year-end adjustments such as depreciation, and similar non-routine entries.', 'https://simplestudy.com/za/nsc/grade-10/accounting/revision-notes/financial-accounting/bookkeeping-of-a-sole-trader-journals/general-journal', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 8, 12, 'term', 'General Ledger, Debtors Ledger, Creditors Ledger', 'The General Ledger holds the accounts (assets, liabilities, owner''s equity, income, expenses). The Debtors Ledger and Creditors Ledger are subsidiary ledgers with an account for each debtor or creditor. Debtors Control and Creditors Control are accounts in the General Ledger. Totals of the journals are posted to the General Ledger at the end of the month.', 'https://simplestudy.com/za/nsc/grade-10/accounting/revision-notes/financial-accounting/bookkeeping-of-a-sole-trader-key-concepts/the-accounting-cycle', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 8, 12, 'term', 'Accounting equation', 'Assets = Owner''s equity + Liabilities.', 'https://simplestudy.com/za/nsc/grade-10/accounting/revision-notes/financial-accounting/bookkeeping-of-a-sole-trader-key-concepts/the-accounting-cycle', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 8, 12, 'rule', 'Which journal for which transaction', 'Cash or EFT received (including from debtors) goes in the Cash Receipts Journal. Cash or EFT paid out (including to creditors and for cash purchases) goes in the Cash Payments Journal. Credit sales: Debtors Journal. Credit purchases: Creditors Journal. A debtor paying their account is a Cash Receipts Journal entry that credits Debtors Control. Paying a creditor is a Cash Payments Journal entry that debits Creditors Control.', 'https://www.graemecollege.co.za/media/1234/grade-9-ems-creditors-notes.pdf', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 8, 12, 'rule', 'Never invent journal names', 'Only use the journal names in the reference: Cash Receipts Journal, Cash Payments Journal, Petty Cash Journal, Debtors Journal, Creditors Journal, Debtors Allowances Journal, Creditors Allowances Journal, General Journal. The abbreviations CRJ and CPJ are ALWAYS the cash journals, never anything to do with creditors.', 'https://www.twinkl.com/teaching-wiki/crj-and-cpj', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 8, 10, 'rule', 'Depreciation in Grades 8 to 10', 'Straight-line depreciation is a fixed percentage of the COST price every year. Diminishing balance depreciation is a fixed percentage of the CARRYING VALUE each year. Carrying value = cost price minus accumulated depreciation. Do not use residual or scrap value, and always state the percentage rate in the question.', 'https://www.scribd.com/document/678625323/CH5', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 9, 12, 'rule', 'Depreciation entries', 'Depreciation is an expense: debit Depreciation, credit Accumulated depreciation, recorded at year end in the General Journal.', 'https://simplestudy.com/za/nsc/grade-10/accounting/revision-notes/financial-accounting/bookkeeping-of-a-sole-trader-key-concepts/the-accounting-cycle', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 7, 12, 'rule', 'Rand notation', 'Write amounts as R1 500 or R240 000 with a space as the thousands separator.', null, 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 1, 12, 'fact', 'South African VAT rate', 'The standard VAT rate in South Africa is 15%. The proposed 2025 increase to 15.5% never took effect and the rate stayed at 15% in 2026. Always use 15% in VAT calculations unless the question gives another rate.', 'https://lookuptax.com/tax-changes/south-africa/rates-act-3-vat-reversal-2026', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 10, 12, 'fact', 'VAT registration threshold', 'From 1 April 2026 the compulsory VAT registration threshold is R2,3 million of taxable turnover in 12 months and the voluntary threshold is R120 000.', 'https://lookuptax.com/docs/country/south-africa', 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 7, 12, 'avoid', 'Creditors'' Receipts Journal', 'This journal does not exist. Money received from debtors is recorded in the Cash Receipts Journal (CRJ), crediting Debtors Control.', null, 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 7, 12, 'avoid', 'Creditors'' Payments Journal', 'This journal does not exist. Payments to creditors are recorded in the Cash Payments Journal (CPJ), debiting Creditors Control.', null, 'approved', 'seed', now()),
  ('{accounting,ems,economic and management}', 7, 12, 'avoid', 'Debtors'' Receipts Journal', 'This journal does not exist in CAPS. Use the Cash Receipts Journal.', null, 'approved', 'seed', now()),
  ('{*}', 1, 12, 'rule', 'South African conventions', 'Use South African English spelling and terms (metre, litre, colour, maths). Use rands (R) for money and metric units. Never use US currency, miles, inches, Fahrenheit, or American terms.', null, 'approved', 'seed', now()),
  ('{*}', 1, 12, 'rule', 'Never invent terms', 'Only use technical terms, abbreviations, document names and formulas that you are certain are used in the South African CAPS curriculum. If a learner''s abbreviation is not in the verified reference and you are not certain what it means, do not guess: write about something else or use the plain full term you are sure of.', null, 'approved', 'seed', now()),
  ('{*}', 1, 12, 'rule', 'Numbers must be checked', 'Any question with a calculation must have every figure worked out step by step before the answer is written, and the figures in the question must be consistent with the answer. If a memo contains a number, that number must be reproducible from the question.', null, 'approved', 'seed', now())
